        'usage: rebuilt ${ledger.segments.length} segment(s), '
        '${ledger.total.totals.requests} request(s), '
        '${ledger.total.totals.input} in / '
        '${ledger.total.totals.output} out '
        '(${ledger.total.source.wire})',
