      return;
    }
    final existing = await UsageLedgerWriter(_env).read(dir);
    if (existing == null) {
      io.writeln(
        'usage: no usage.json for this session yet — run a turn, then '
        '/usage rebuild',
      );
      return;
    }
    io.writeln(
