    this.quotaTtl,
    this.quotaHttpClient,
    this.tuiTheme,
    this.tuiProgramHooks,
    this.sttyRunner,
    this.openRouterOAuthExchangeFn,
    this.chatGptOAuthExchangeFn,
    this.aiinConnectFn,
    this.copilotDeviceFlowFn,
