        segmentMarkerLine(1),
        requestSummaryLine(2),
        assistantLine(
          3,
          model: 'model-old',
          usage: reportedUsage(input: 100, output: 50),
        ),
        segmentMarkerLine(4),
        requestSummaryLine(5),
        assistantLine(
